 return f'<section class="page-hero"><div class="wrap"><p class="breadcrumb"><a href="index.html">{crumb.split(" /")[0]}</a> / {html.escape(title)}</p><div class="eyebrow">LAWYGO PAN</div><h1>{html.escape(title)}</h1><p>{html.escape(desc)}</p></div></section>'
