LAWYERS=[('김서현','기업·계약','서울','legal-consultant','기업 자문과 계약 검토, 사업 운영의 법률 쟁점을 이해하기 쉽게 설명합니다.','lawyer-kim.html'),('이준호','가사·상속','서울','male-attorney','이혼·재산분할·상속 상담에서 확인할 사항을 안내합니다.','lawyer-lee.html'),('박지민','부동산·임대차','경기','hero-attorney','전세·임대차·부동산 계약 분쟁에서 확인할 절차를 정리합니다.','lawyer-park.html'),('정도현','형사·민사','서울','lawyer-video','형사 절차와 민사 분쟁 관련 기초 정보를 제공합니다.','lawyer-jung.html')]
def laycards():
 out='';
 for n,cat,region,im,desc,link in LAWYERS:
  out+=f'''<article class="lawyer-card shadow" data-search="{n} {cat} {region} 변호사 소송 법률" data-category="{cat}" data-region="{region}"><img src="assets/{im}.webp" alt="{n} 변호사 시연용 가상 인물 사진" loading="lazy"><div><span class="tag demo">가상 인물 · 시연용</span><h3>{n} <small class="muted">변호사 프로필 시안</small></h3><div><span class="tag">{cat}</span><span class="tag">{region}</span></div><p>{desc}</p></div><div class="end"><a class="btn outline" href="{link}">프로필 보기</a><a class="btn primary" href="consultation.html?lawyer={n}">상담 신청</a></div></article>'''
 return out

add('index.html','좋은 변호사를, 더 가까이','법률 블로그와 영상, 변호사 프로필을 하나의 검색 경험으로 연결합니다.',f'''<section class="hero"><div class="wrap"><div class="hero-content"><div class="eyebrow rose">LAWYGO PAN · LEGAL CONTENT & EXPERTS</div><h1>법이 필요한 순간,<br><span style="color:#a67848">더 가까운 전문가.</span></h1><p>검색으로 시작하고, 콘텐츠로 이해하고, 상담으로 연결하세요. 로이고 판은 전문 분야·지역·블로그·영상 정보를 한곳에 모은 변호사 마케팅 플랫폼입니다.</p><form class="searchbox" data-search-form><input aria-label="법률 문제 검색" placeholder="어떤 법률 문제가 궁금하신가요?"><button type="submit" class="btn primary">변호사 찾기 ↗</button></form><div class="chips">{''.join(f'<a class="chip" href="lawyers.html?q={q}">{q}</a>' for q in ['이혼','상속','부동산','기업 자문','민사','형사'])}</div><div class="notice" style="margin-top:26px;max-width:540px">※ 현재 공개 시안에는 시연용 프로필과 예시 콘텐츠가 포함되어 있습니다. 실제 변호사 검증과 상담 연결은 운영 시스템 구축 후 제공됩니다.</div></div></div></section><section class="stat-strip"><div class="wrap">{''.join(f'<div class="stat"><b>{a}</b><p>{b}</p></div>' for a,b in [('01','분야별 탐색'),('02','프로필·콘텐츠 확인'),('03','상담 문의'),('04','전문가의 직접 응대')])}</div></section><section class="section"><div class="wrap"><div class="eyebrow">DISCOVER</div><h2>필요한 법률 서비스를 빠르게 찾으세요.</h2><div class="grid g4">{''.join(f'<a href="{u}" class="surface quick-card shadow"><div class="circle-icon">{ic}</div><h3>{t}</h3><p>{d}</p></a>' for ic,t,d,u in [('⚖','변호사 찾기','분야·지역별 프로필','lawyers.html'),('▤','변호사 블로그','전문가가 쓴 법률 칼럼','blog.html'),('▶','유튜브 영상','영상으로 이해하는 법률','videos.html'),('✉','상담 신청','간단한 문의 내용 작성','consultation.html')])}</div></div></section><section class="section bg-cream"><div class="wrap"><div style="display:flex;align-items:end;justify-content:space-between;gap:15px"><div><div class="eyebrow">PRACTICE AREAS</div><h2>분야별로 만나보는 법률 전문가</h2></div><a class="btn outline" href="categories.html">전체 분야 보기</a></div><div class="grid g4">{''.join(f'<a class="surface pad" href="lawyers.html?q={q}"><div class="circle-icon" style="margin:0 0 14px">{ic}</div><h3>{name}</h3><p class="small muted">{d}</p></a>' for ic,name,q,d in [('♡','이혼·가사','이혼','이혼, 양육권, 재산분할'),('⌂','부동산','부동산','임대차, 보증금, 매매'),('▣','기업·계약','기업','계약서, 인사, 스타트업'),('⚖','형사·민사','형사','고소, 분쟁, 손해배상')])}</div></div></section><section class="section"><div class="wrap"><div class="eyebrow">EXPERT SHOWCASE</div><h2>전문가 프로필을 먼저 둘러보세요.</h2><p class="muted">인물과 소개는 디자인 검토용 예시입니다. 실제 변호사와의 연관성은 없습니다.</p><div class="grid g2">{laycards()}</div><p class="right" style="margin-top:17px"><a href="lawyers.html" class="btn outline">변호사 전체 보기 ↗</a></p></div></section><section class="section bg-cream"><div class="wrap"><div class="eyebrow">EDITORIAL & VIDEO</div><h2>읽고 보는 법률 콘텐츠</h2><div class="grid g3">{card('law-books','BLOG / CONTRACT','계약서를 작성하기 전 확인할 기본 조항','분쟁을 줄이는 계약서 체크리스트','blog-detail.html')}{card('legal-podcast','VIDEO / BUSINESS','기업 자문: 계약 체결 전 무엇을 확인할까?','변호사가 말하는 실무 체크포인트','video-detail.html')}{card('conference-office','INSIGHTS / BUSINESS','스타트업과 기업이 알아둘 법률 위험','의사결정 전 점검할 필수 사항','stories.html')}</div></div></section><section class="section bg-navy"><div class="wrap"><div class="grid g2" style="align-items:center"><div><p class="eyebrow">FOR LEGAL PROFESSIONALS</p><h2>변호사의 전문성을<br>콘텐츠로 증명하세요.</h2><p class="muted-on-dark">Google Blogger와 YouTube 게시물을 전문 프로필에 연결해 검색과 상담 유입으로 이어지는 브랜디드 페이지를 계획합니다.</p><a href="join.html" class="btn gold">파트너 변호사 등록 안내 ↗</a></div><img class="image-object" src="assets/conference-office.webp" alt="법률 전문가의 현대적 업무 공간" loading="lazy"></div></div></section>''')

add('lawyers.html','변호사 찾기','전문 분야와 지역, 소개 콘텐츠를 비교하여 상담할 전문가를 찾으세요.',pagehead('변호사 찾기','분야와 지역을 선택해 변호사 프로필을 살펴보세요.')+f'''<section class="section"><div class="wrap"><div class="searchbox" style="max-width:100%"><input id="lawyer-q" placeholder="이름, 전문 분야, 지역으로 검색" aria-label="변호사 검색어"><button class="btn primary" type="button" onclick="document.getElementById('lawyer-q').dispatchEvent(new Event('input'))">검색</button></div><div class="filterbar" style="margin:22px 0" data-category-current="전체">{''.join(f'<button class="chip {"active" if i==0 else ""}" data-filter-category="{x}">{x}</button>' for i,x in enumerate(['전체','기업·계약','가사·상속','부동산·임대차','형사·민사']))}<select class="field" id="filter-region" aria-label="지역" style="max-width:170px"><option>전체</option><option>서울</option><option>경기</option></select></div><div class="sidebar-layout"><aside class="surface sidebar"><b>검색 안내</b><p class="small muted">검색 결과는 시연용 가상 프로필입니다.</p><div class="divider"></div><h4>상담 전 확인</h4><ul class="checklist"><li>등록 자격 확인</li><li>전문 분야 확인</li><li>예상 비용 문의</li><li>개인정보 최소 제공</li></ul><a class="btn outline block" href="consultation-guide.html">상담 이용 가이드</a></aside><div><p class="small muted" id="lawyer-count">4명의 시연용 전문가 프로필</p><div class="grid-list" id="lawyer-directory">{laycards()}</div><p class="empty surface" id="lawyer-empty">조건에 맞는 시연용 프로필이 없습니다. 검색 조건을 바꿔 주세요.</p></div></div></div></section>''')

add('categories.html','전문 분야','상담 주제를 기준으로 법률 정보를 찾고, 관련 전문가를 탐색하세요.',pagehead('전문 분야','잘 모르는 법률 문제도 익숙한 주제부터 찾아보세요.')+'''<section class="section"><div class="wrap"><div class="grid g3">'''+''.join(f'<a href="{url}" class="surface pad shadow"><div class="eyebrow">AREA {i:02d}</div><h3>{name}</h3><p class="muted small">{desc}</p><span style="color:#ac7e43">살펴보기 →</span></a>' for i,(name,desc,url) in enumerate([('이혼·가사','이혼, 재산분할, 양육권, 친권','category-family.html'),('기업·계약','기업 자문, 계약, 노동·인사, 개인정보','category-business.html'),('부동산·임대차','보증금, 임대차, 건물·토지','lawyers.html?q=부동산'),('형사·범죄','고소·고발, 수사, 형사재판','lawyers.html?q=형사'),('민사·손해배상','채권, 손해배상, 계약 분쟁','lawyers.html?q=민사'),('상속·유언','상속재산, 유류분, 상속포기','lawyers.html?q=상속'),('노동·인사','부당해고, 임금, 근로계약','lawyers.html?q=노동'),('지식재산·IT','저작권, 상표, 기술·정보보호','lawyers.html?q=기업'),('행정·조세','인허가, 세무, 행정처분','lawyers.html?q=기업')],1))+'''</div></div></section>''')
for slug,title,body,img,query in [('category-family.html','이혼·가사','이혼·가사 분야는 혼인 관계의 해소뿐 아니라 재산분할, 자녀의 양육, 친권·양육비, 위자료 등 다양한 문제를 함께 다룹니다. 현재 상황과 관련 서류를 정리하고, 기한이 있는 절차인지 먼저 확인해 보세요.','client-meeting','이혼'),('category-business.html','기업·계약','기업 법무는 계약 위험 관리, 주주·지분 관계, 채권 회수, 노동·인사, 개인정보와 지식재산권 문제까지 폭넓게 연결됩니다. 계약 체결 전에는 당사자, 의무·대금, 해지·손해배상, 분쟁 해결 조항을 점검하는 것이 좋습니다.','conference-office','기업')]:
 add(slug,title,f'{title} 관련 주요 쟁점과 전문가 탐색',pagehead(title,'분야의 기본 개념을 이해하고 관련 변호사 정보를 확인하세요.')+f'''<section class="section"><div class="wrap grid g2" style="align-items:center"><div><div class="eyebrow">PRACTICE GUIDE</div><h2>처음부터 차근차근, 중요한 쟁점을 확인하세요.</h2><p>{body}</p><ul class="checklist"><li>문제 발생 경위와 주요 날짜 정리</li><li>계약서·통지서 등 관련 자료 정리</li><li>소멸시효·불복기간 등 기한 확인</li><li>신뢰할 수 있는 전문가에게 직접 상담</li></ul><a class="btn primary" href="lawyers.html?q={query}">관련 변호사 찾기 ↗</a></div><img src="assets/{img}.webp" alt="{title} 분야 관련 업무 장면" class="image-object"></div></section><section class="section bg-cream"><div class="wrap"><h2>상담 전에 준비하면 좋은 내용</h2><div class="grid g3">{''.join(f'<div class="surface pad"><div class="eyebrow">0{i}</div><h3>{heading}</h3><p class="muted small">{txt}</p></div>' for i,(heading,txt) in enumerate([('사실관계','누가, 언제, 어떤 일을 겪었는지 정리합니다.'),('관련 자료','계약서, 문자, 입금내역 등 필요한 자료를 선별합니다.'),('상담 목표','원하는 해결 방법과 궁금한 점을 적어 둡니다.')],1))}</div></div></section>''')

